-- 1: Define table variable
CREATE OR REPLACE TEMPORARY TABLE
	UTIL.TMP_ADF_COPY_CONTROL (
		ADF_COPY_CONTROL_KEY NUMBER(38,0) NOT NULL,
		INSERT_DATETIME TIMESTAMP_TZ(9), 
		LAST_UPDATED_DATETIME TIMESTAMP_TZ(9), 
		IS_ACTIVE BOOLEAN NOT NULL, 
		SOURCE_DATABASE_TYPE VARCHAR NOT NULL,
		SOURCE_QUERY VARCHAR NOT NULL, 
		TARGET_BLOB_LOCATION VARCHAR NOT NULL,
		TARGET_TABLE_NAME VARCHAR,
		IS_INCREMENTAL BOOLEAN NOT NULL,
		SOURCE_DATABASE_SECRET_VALUE VARCHAR, 
		SOURCE_TABLE_NAME VARCHAR NOT NULL,
		VARIABLE_DATE_FORMAT VARCHAR,
		COPY_INTO_QUERY_DATE_FORMAT VARCHAR, 
		SOURCE_COLUMN_NAMES VARCHAR,
		FILTER_QUERY_COLUMN_NAME VARCHAR,
		TRIGGER_NAME VARCHAR,
		SOURCE_DATABASE_NAME VARCHAR,
		CONSTRAINT PK_ADF_COPY_CONTROL PRIMARY KEY (ADF_COPY_CONTROL_KEY),
		CONSTRAINT UK_ADF_COPY_CONTROL UNIQUE (TARGET_TABLE_NAME)
	) COMMENT = 'Control table for copying tables from database tables via ADF.'
;
-- 2: Populate the table variable with data
-- This is where you manage your data in source control. You
-- can add and modify entries, but because of potential foreign
-- key contraint violations this script will not delete any
-- removed entries. If you remove an entry then it will no longer
-- be added to new databases based on your schema, but the entry
-- will not be deleted from databases in which the value already exists.

!set variable_substitution=true;
;


!set variable_substitution=false;

-- 3: Insert any new items into the table from the table variable
SELECT TMP.ADF_COPY_CONTROL_KEY, TMP.INSERT_DATETIME, TMP.LAST_UPDATED_DATETIME, TMP.IS_ACTIVE, TMP.SOURCE_DATABASE_TYPE, TMP.SOURCE_QUERY, TMP.TARGET_BLOB_LOCATION, TMP.TARGET_TABLE_NAME, TMP.IS_INCREMENTAL, TMP.SOURCE_DATABASE_SECRET_VALUE, TMP.SOURCE_TABLE_NAME, TMP.VARIABLE_DATE_FORMAT, TMP.COPY_INTO_QUERY_DATE_FORMAT, TMP.SOURCE_COLUMN_NAMES, TMP.FILTER_QUERY_COLUMN_NAME, TMP.TRIGGER_NAME, TMP.SOURCE_DATABASE_NAME
FROM UTIL.TMP_ADF_COPY_CONTROL TMP
	LEFT JOIN UTIL.ADF_COPY_CONTROL TB1 ON TB1.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
WHERE TB1.ADF_COPY_CONTROL_KEY IS NULL;

-- 4: Update any modified values with the values from the table variables
UPDATE UTIL.ADF_COPY_CONTROL LIVE_TABLE
SET
LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY,
LIVE_TABLE.LAST_UPDATED_DATETIME = TMP.LAST_UPDATED_DATETIME,
LIVE_TABLE.IS_ACTIVE = TMP.IS_ACTIVE,
LIVE_TABLE.SOURCE_DATABASE_TYPE = TMP.SOURCE_DATABASE_TYPE,
LIVE_TABLE.SOURCE_QUERY = TMP.SOURCE_QUERY,
LIVE_TABLE.TARGET_BLOB_LOCATION = TMP.TARGET_BLOB_LOCATION,
LIVE_TABLE.TARGET_TABLE_NAME = TMP.TARGET_TABLE_NAME,
LIVE_TABLE.IS_INCREMENTAL = TMP.IS_INCREMENTAL,
LIVE_TABLE.SOURCE_DATABASE_SECRET_VALUE = TMP.SOURCE_DATABASE_SECRET_VALUE,
LIVE_TABLE.SOURCE_TABLE_NAME = TMP.SOURCE_TABLE_NAME,
LIVE_TABLE.VARIABLE_DATE_FORMAT = TMP.VARIABLE_DATE_FORMAT,
LIVE_TABLE.COPY_INTO_QUERY_DATE_FORMAT = TMP.COPY_INTO_QUERY_DATE_FORMAT,
LIVE_TABLE.SOURCE_COLUMN_NAMES = TMP.SOURCE_COLUMN_NAMES,
LIVE_TABLE.FILTER_QUERY_COLUMN_NAME = TMP.FILTER_QUERY_COLUMN_NAME,
LIVE_TABLE.TRIGGER_NAME = TMP.TRIGGER_NAME,
LIVE_TABLE.SOURCE_DATABASE_NAME = TMP.SOURCE_DATABASE_NAME
FROM UTIL.TMP_ADF_COPY_CONTROL TMP
WHERE LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
;

SELECT 'Finished updating the static data table UTIL.ADF_COPY_CONTROL';